import {CHAPTERS,SHIPS,ENEMIES,DIFFICULTIES,stageConfig} from './data.js?v=30.1';
import {missionCleared,bossUnlocked,storyTarget,latestClear,ACHIEVEMENTS} from './campaign.js?v=30.1';
import {getLocale} from './i18n.js?v=30.1';
const pad=n=>String(n).padStart(2,'0'),text=values=>values[['zh','ja','en'].indexOf(getLocale())];
const source=meta=>meta?.fallback||meta?.src||'';
export function flightOptionsHtml(selection){return `<span class="selection-label">难度 / DIFFICULTY</span><div class="segmented">${DIFFICULTIES.map(d=>`<button class="${selection.difficulty===d.id?'active':''}" data-action="difficulty" data-value="${d.id}" aria-pressed="${selection.difficulty===d.id}">${d.name}</button>`).join('')}</div><p class="tiny-note">休闲难度适合新手，标准保持均衡；复杂难度敌机数量与耐久增加，敌方弹幕和技能频次适度降低，为三条命与单次受击机制保留躲避空间。</p><span class="selection-label">节奏 / MISSION LENGTH</span><div class="segmented">${[['quick','快速试飞','75 秒波次 · Boss 另计'],['full','完整波次','150 秒波次 · Boss 另计']].map(([id,name,note])=>`<button class="${selection.pace===id?'active':''}" data-action="pace" data-value="${id}">${name}<small>${note}</small></button>`).join('')}</div>`;}
export function storyModeHtml(profile,selection){const m=storyTarget(profile);return `<p class="modal-note">按顺序推进九章二十七个小关。通关后战机飞离战场，自动返回机库；选择战机、完成升级后，再出击下一关。</p>${m?`<div class="route-summary"><span>${pad(m.chapter+1)}—${pad(m.substage+1)}</span><h3>${CHAPTERS[m.chapter].name}</h3><p>${CHAPTERS[m.chapter].locations[m.substage]}</p></div>`:'<div class="empty-state">九章故事已全部通关。可以从第一关重新开始，保留现有升级和通关记录。</div>'}${flightOptionsHtml(selection)}${m?`<button class="primary" data-action="story-launch">故事出击 ↗</button>`:''}<button class="secondary" data-action="story-new">从第一关开始 ↗</button><p class="tiny-note">通关进度和升级自动保存在此浏览器。</p>`;}
export function continueHtml(profile,selection){const m=latestClear(profile);return `<p class="modal-note">自动读取已通关的最远小关，从该关开头继续作战。新的通关会更新续玩关卡。</p>${m?`<div class="route-summary"><span>${pad(m.chapter+1)}—${pad(m.substage+1)}</span><h3>${CHAPTERS[m.chapter].name}</h3><p>${CHAPTERS[m.chapter].locations[m.substage]}</p></div><p>${SHIPS[selection.ship].name} · ${DIFFICULTIES.find(d=>d.id===m.difficulty).name} · ${m.pace==='full'?'完整波次':'快速试飞'}</p><button class="primary" data-action="continue-launch">读取存档并出击 ↗</button>`:'<div class="empty-state">还没有通关记录。先完成故事模式第一小关，即可使用继续战斗。</div><button class="primary" data-action="open-story">进入故事模式 ↗</button>'}`;}
export function missionsHtml(profile,selection,manifest){const ch=CHAPTERS[selection.chapter],stage=stageConfig(selection.chapter,selection.substage,'campaign',selection.pace),ready=missionCleared(profile,selection.chapter,selection.substage);return `<p class="modal-note">关卡选择用于重玩已通关的小关。完成故事模式后，对应关卡才会开放。</p><div class="chapter-grid">${CHAPTERS.map((c,i)=>{const open=[0,1,2].some(s=>missionCleared(profile,i,s));return `<button class="chapter-card ${selection.chapter===i?'active':''} ${open?'':'locked'}" data-action="chapter" data-value="${i}" ${open?'':'disabled'} aria-label="第 ${i+1} 章 ${c.name}" aria-pressed="${selection.chapter===i}"><span class="thumb"><img src="${source(manifest.backgrounds[i+1])}" alt="${c.name}环境" loading="lazy"></span><span class="chapter-code">C / ${pad(i+1)} ${open?'':'🔒'}</span><strong>${c.name}</strong><small>${[0,1,2].map(s=>missionCleared(profile,i,s)?'★':'·').join(' ')} / 3 MISSIONS</small></button>`;}).join('')}</div><span class="selection-label">小关 / FLIGHT ROUTE</span><div class="segmented">${ch.locations.map((name,i)=>{const open=missionCleared(profile,selection.chapter,i);return `<button class="${selection.substage===i?'active':''}" data-action="substage" data-value="${i}" ${open?'':'disabled'}>${selection.chapter+1}—${i+1}${open?'':' 🔒'}<small>${name}</small></button>`;}).join('')}</div><div class="selected-mission"><h3>${stage.name}</h3><p>${ready?ch.stories[selection.substage]:'通关后开放重玩'}</p><div class="enemy-roster">${stage.enemies.map(id=>`<div><img src="${source(manifest.enemies[id])}" alt="${ENEMIES[id-1].name}" loading="lazy"><small>E${pad(id)} / ${ENEMIES[id-1].name}</small></div>`).join('')}</div></div>${flightOptionsHtml(selection)}<button class="primary" data-action="launch" ${ready?'':'disabled'}>驾驶 ${SHIPS[selection.ship].name} 出击 ↗</button>${ready?'':'<button class="secondary" data-action="open-story">进入故事模式 ↗</button>'}`;}
export function bossChallengeHtml(profile,selection,manifest){const ready=bossUnlocked(profile,selection.chapter),ch=CHAPTERS[selection.chapter];return `<p class="modal-note">完成本章第三小关后，解锁对应首领挑战。挑战胜利单独记录成绩。</p><div class="chapter-grid boss-challenge-grid">${CHAPTERS.map((c,i)=>{const open=bossUnlocked(profile,i);return `<button class="chapter-card ${selection.chapter===i?'active':''} ${open?'':'locked'}" data-action="boss-chapter" data-value="${i}" ${open?'':'disabled'} aria-pressed="${selection.chapter===i}"><span class="thumb"><img src="${manifest.story?.bossPortraitFallbacks?.[i]||source(manifest.bosses[i+1])}" alt="${c.boss}" loading="lazy"></span><span class="chapter-code">B / ${pad(i+1)} ${open?'':'🔒'}</span><strong>${c.boss}</strong><small>${profile.bossClears[i]?'★'.repeat(profile.bossClears[i]):open?'已解锁':'待解锁'}</small></button>`;}).join('')}</div><div class="route-summary"><span>B / ${pad(selection.chapter+1)}</span><h3>${ch.boss}</h3><p>${ready?'已解锁':'完成本章第三小关后解锁'}</p></div><span class="selection-label">难度 / DIFFICULTY</span><div class="segmented">${DIFFICULTIES.map(d=>`<button class="${selection.difficulty===d.id?'active':''}" data-action="difficulty" data-value="${d.id}">${d.name}</button>`).join('')}</div><p class="tiny-note">首领挑战使用完整血量和对应的专属战斗音乐。</p><button class="primary" data-action="boss-launch" ${ready?'':'disabled'}>挑战首领 ↗</button>`;}
export function hangarRouteHtml(profile){const m=storyTarget(profile);return `<div class="hangar-route"><span class="selection-label">故事航线</span>${m?`<strong>${pad(m.chapter+1)}—${pad(m.substage+1)} · ${CHAPTERS[m.chapter].name}</strong><p>选择战机并升级，然后继续下一关。</p><button class="primary" data-action="story-launch">下一关出击 ↗</button>`:`<strong>九章故事已全部通关</strong><button class="secondary" data-action="open-story">进入故事模式 ↗</button>`}</div>`;}
export function achievementsHtml(profile){const won=new Set(profile.achievements||[]);return `<p class="modal-note">成就根据真实通关、发现和升级记录解锁，自动保存。</p><div class="wallet"><span>已解锁成就 <b>${won.size} / ${ACHIEVEMENTS.length}</b></span><span>已通关小关 <b>${Object.keys(profile.clears).length} / 27</b></span></div><div class="achievement-grid">${ACHIEVEMENTS.map(a=>`<article class="achievement-card ${won.has(a.id)?'earned':'locked'}"><span aria-hidden="true">${won.has(a.id)?'✦':'🔒'}</span><div><h3>${text(a.name)}</h3><p>${text(a.note)}</p><small>${won.has(a.id)?'已解锁':'待解锁'}</small></div></article>`).join('')}</div>`;}
